    final Map<String, Integer> counts = new ConcurrentHashMap<>();
    final List<String> syncTargets = Collections.synchronizedList(new ArrayList<>());
    long uid;
    int readers;
    int writers;
    int listings;
    int failAt = 1;
    int hookAt = 1;
    int partSequence;
    String fail = "";
    String hookName = "";
    String invalid = "";
    String badRole = "";
    String listingFault = "";
    boolean triggered;
    boolean rawCloses;
    boolean nullPart;
    boolean overfillReader;
    RuntimeException runtimeFailure;
