                    USER,
                    new VideoDescriptorRequestData("opening")));
      failure(
          ResultCode.TEMPORARY_FAILURE,
          () ->
              QUERIES.videoMetadata(
                  fault(c, "overrideString", "category", "UNKNOWN"),
