                  new VideoDescriptorRequestData("opening")));
      String[][] invalid = {
        {"storage_relative_path", "video/wrong.ogg"},
        {"storage_relative_path", "music/wrong.bin"},
        {"storage_relative_path", "music/../wrong.ogg"},
        {"storage_relative_path", "music/" + "あ".repeat(84) + ".ogg"},
        {"file_name", "wrong.mp4"},
