      assertWire(
          segmented,
          descriptorBytes(
              "media", "music/" + "a".repeat(251) + ".ogg", "file.ogg", "audio/ogg", "I"),
          List.of());
    }
  }

  private static Optional<TypedPayloadValues> metadata(
      String kind, Connection c, AuthenticatedActor actor) {
    return switch (kind) {
      case "audio" ->
          QUERIES.audioMetadata(
              c,
