        display_path,file_name,byte_size,sha256,mime_type,parent_logical_id,pair_key,pair_role,display_order,created_at)
      values(?,?,?,?,?,?,?,?,?,123,repeat('a',64),?,?,?,?,?,'2026-09-08Z')
