      assertFalse(a.skipped());
      assertFalse(c.isClosed());
      assertFalse(c.getAutoCommit());
      assertFalse(c.isReadOnly());
      assertEquals(Connection.TRANSACTION_READ_COMMITTED, c.getTransactionIsolation());
