          List.of("nullStatement", "nullRows", "empty", "extra", "id", "badIdLow", "badIdHigh")) {
        Probe p = new Probe();
        p.kind = "insert";
        p.anomaly = bad;
        redacted(() -> new BatchRunRepository(p.wrap(c)).begin(RUN, STEP, NOW, false));
        p.closed();
        c.rollback();
        assertEquals("0", query(c, "select count(*) from schubert.batch_runs"));
      }
    }
  }

